create extension if not exists pgcrypto;create table profiles(id uuid primary key,full_name text not null,role text not null check(role in('section_head','teacher')),active boolean default true);create table classes(id uuid primary key default gen_random_uuid(),name text unique not null,grade int not null);create table students(id uuid primary key default gen_random_uuid(),admission_no text unique not null,full_name text not null,class_id uuid references classes(id),active boolean default true);create table teacher_class_assignments(teacher_id uuid references profiles(id),class_id uuid references classes(id),primary key(teacher_id,class_id));create table attendance_sessions(id uuid primary key default gen_random_uuid(),class_id uuid references classes(id),attendance_date date not null,submitted_by uuid references profiles(id),submitted_at timestamptz,unique(class_id,attendance_date));create table attendance_records(id uuid primary key default gen_random_uuid(),session_id uuid references attendance_sessions(id) on delete cascade,student_id uuid references students(id),status text not null check(status in('present','absent','late')),updated_at timestamptz default now(),unique(session_id,student_id));create table attendance_changes(id bigint generated always as identity primary key,attendance_record_id uuid references attendance_records(id),old_status text,new_status text,changed_by uuid references profiles(id),changed_at timestamptz default now(),reason text);create table holidays(id uuid primary key default gen_random_uuid(),holiday_date date unique not null,name text not null);create table audit_logs(id bigint generated always as identity primary key,user_id uuid references profiles(id),action text not null,target_type text,target_id text,details jsonb,created_at timestamptz default now());insert into classes(name,grade) values ('10-A',10),('10-B',10),('10-C',10),('10-D',10),('10-E',10),('11-A',11),('11-B',11),('11-C',11),('11-D',11),('11-E',11) on conflict do nothing;alter table profiles enable row level security;alter table students enable row level security;alter table attendance_sessions enable row level security;alter table attendance_records enable row level security;